    const ja = d.querySelector('#karte-rumpf .loesch-frage [data-do="bearb-weg-ja"]');
    if (ja) { ja.click(); await tick(); await tick(); }
    pruef('Löschen wirft keinen Laufzeitfehler', lf() === vorLf, fehler.slice(-1)[0]);
