    pruef('3.31.0: edits und weg stehen nicht mehr in den Grundwerten', gw.indexOf('edits') < 0 && gw.indexOf('weg') < 0);

    /* Sperre: Mit Daten wartet die Bereinigung auf die Sicherung */
