    pruef('beta.1: Die Sicherung trägt die Beta-Fassung', JSON.parse(T('sicherungInhalt()')).__fassung === T('FASSUNG'));

    /* sw.js mit Attrappen: löscht nur eigene alte Stände */
    const vm = require('vm');
