      pruef('beta.10: Wasserstand ein Viertel der Topfhöhe, 2 bis 6 cm', T('gmWasserstandCm(8)') === 2 && T('gmWasserstandCm(20)') === 4 && T('gmWasserstandCm(60)') === 6);
