      d.getElementById('f-name').value = 'Mix15';
      T(`(function(){ formLageZeichnen(raumAnlegen('Prüfraum 15'), ''); var t = document.getElementById('f-topf'); t.value = '14'; t.dataset.gesetzt = '1'; alTopfZeichnen(); return 1; })()`);
