      const gm = () => T(`(function(){ gmListeBauen(); return JSON.stringify(gmListe.reduce(function(a, x){ return a.concat(x.pflanzen ? x.pflanzen.map(function(p){ return p.id; }) : (x.id ? [x.id] : [])); }, []).sort()); })()`);
