      /* Tag setzen: Gießtag ersetzt den laufenden, mit Hinweis */
      T(`(function(){ S.tagEin.G1 = [{e:'e-k1', t:'${kTag}', von:'${plus(-4)}', bis:null, ende:null, notiz:'', pz:25}]; sichern(); return 1; })()`);
      const v1k = stand('G1');
